<template><Teleport to="body"><Transition name="command"><div v-if="open" class="command-layer" @mousedown.self="$emit('close')"><section class="command" role="dialog" aria-label="命令菜单"><div class="command__search"><LnIcon name="search"/><input ref="input" v-model="query" placeholder="输入命令或搜索…" @keydown.esc="$emit('close')" @keydown.down.prevent="move(1)" @keydown.up.prevent="move(-1)" @keydown.enter.prevent="runActive"/><kbd>ESC</kbd></div><div class="command__results"><span class="command__group">{{query?'搜索结果':'建议'}}</span><button v-for="(item,index) in filtered" :key="item.value" type="button" :class="{'is-active':index===active}" @mouseenter="active=index" @click="run(item)"><i><LnIcon :name="resolveIcon(item)"/></i><span><b>{{item.label}}</b><small v-if="item.description">{{item.description}}</small></span><kbd v-if="item.shortcut">{{item.shortcut}}</kbd></button><div v-if="!filtered.length" class="command__empty">未找到相关命令</div></div></section></div></Transition></Teleport></template>
<script setup lang="ts">
import{computed,nextTick,ref,watch}from'vue';import LnIcon from './LnIcon.vue';export interface CommandItem{label:string;value:string;description?:string;icon?:string;shortcut?:string};const props=defineProps<{open:boolean;items:CommandItem[]}>();const emit=defineEmits<{(e:'close'):void;(e:'select',item:CommandItem):void}>();const query=ref('');const active=ref(0);const input=ref<HTMLInputElement>();const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return q?props.items.filter(i=>(i.label+i.description).toLowerCase().includes(q)):props.items});watch(()=>props.open,value=>{if(value){query.value='';active.value=0;nextTick(()=>input.value?.focus())}});watch(query,()=>active.value=0);function move(delta:number){const count=filtered.value.length;if(count)active.value=(active.value+delta+count)%count}function run(item:CommandItem){emit('select',item);emit('close')}function runActive(){const item=filtered.value[active.value];if(item)run(item)}function resolveIcon(item:CommandItem){const token=`${item.value} ${item.label} ${item.icon}`.toLowerCase();if(/(new|create|plus|新增|新建)/.test(token))return'plus';if(/(user|profile|个人)/.test(token))return'user';if(/(archive|归档)/.test(token))return'archive';if(/(copy|复制)/.test(token))return'copy';return'external-link'}
</script>
<style scoped lang="scss">
.command-layer{position:fixed;z-index:800;inset:0;padding-top:min(18vh,150px);display:flex;justify-content:center;background:rgba(28,28,32,.2);backdrop-filter:blur(2px)}.command{width:min(600px,calc(100vw - 32px));height:max-content;max-height:440px;overflow:hidden;border:1px solid var(--ln-border);border-radius:12px;background:var(--ln-surface-raised);box-shadow:0 22px 70px rgba(20,20,24,.2);font-family:var(--ln-font)}.command__search{height:52px;padding:0 15px;display:flex;align-items:center;gap:10px;border-bottom:1px solid var(--ln-border);color:var(--ln-icon);>svg{width:17px;height:17px}input{min-width:0;flex:1;border:0;outline:0;color:var(--ln-text);font:14px var(--ln-font)}kbd{padding:2px 5px;border:1px solid var(--ln-border);border-radius:4px;background:var(--ln-canvas);font:11px var(--ln-font)}}.command__results{max-height:385px;padding:7px;overflow:auto;display:grid;gap:2px}.command__group{padding:7px 8px 5px;color:var(--ln-text-tertiary);font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.06em}.command__results button{min-height:44px;padding:6px 9px;display:grid;grid-template-columns:22px 1fr auto;align-items:center;gap:8px;border:0;border-radius:6px;background:transparent;color:var(--ln-text);text-align:left;cursor:pointer;&.is-active{background:var(--ln-surface-hover)}i{width:18px;height:18px;display:grid;place-items:center;color:var(--ln-icon);font-style:normal;svg{width:16px;height:16px}}span{display:grid;gap:2px}b{font-size:13px;font-weight:540}small{color:var(--ln-text-tertiary);font-size:11px}kbd{color:var(--ln-text-tertiary);font:11px var(--ln-font)}}.command__empty{padding:36px;text-align:center;color:var(--ln-text-tertiary);font-size:12px}.command-enter-active,.command-leave-active{transition:opacity var(--ln-normal)}.command-enter-active .command,.command-leave-active .command{transition:transform var(--ln-normal),opacity var(--ln-normal)}.command-enter-from,.command-leave-to{opacity:0}.command-enter-from .command,.command-leave-to .command{opacity:0;transform:translateY(-8px) scale(.98)}
</style>
